ABBR = {'Alabama': 'AL', 'Alaska': 'AK', 'Arizona': 'AZ', 'Arkansas': 'AR', 'California': 'CA', 'Colorado': 'CO', 'Florida': 'FL', 'Georgia': 'GA', 'Hawaii': 'HI', 'Idaho': 'ID', 'Indiana': 'IN', 'Iowa': 'IA', 'Kansas': 'KS', 'Kentucky': 'KY', 'Louisiana': 'LA', 'Maryland': 'MD', 'Massachusetts': 'MA', 'Michigan': 'MI', 'Minnesota': 'MN', 'Missouri': 'MO', 'Montana': 'MT', 'Nebraska': 'NE', 'Nevada': 'NV', 'New Hampshire': 'NH', 'New Mexico': 'NM', 'North Carolina': 'NC', 'North Dakota': 'ND', 'Ohio': 'OH', 'Oklahoma': 'OK', 'Oregon': 'OR', 'Rhode Island': 'RI', 'South Carolina': 'SC', 'South Dakota': 'SD', 'Tennessee': 'TN', 'Utah': 'UT', 'Vermont': 'VT', 'Virginia': 'VA', 'Washington': 'WA', 'West Virginia': 'WV', 'Wisconsin': 'WI', 'Wyoming': 'WY'}
out = []
for i, m in enumerate(M):
    if i not in L or m['result'] not in ('a', 'd'): continue
    y = re.search(r'\(([\d.]+)%\)', m['yes'])
    if not y: continue
    yv, nv = re.match(r'([\d,]+)', m['yes']), re.match(r'([\d,]+)', m['no'])
    out.append({'st': ABBR[m['state']], 'title': m['title'].replace('�', ''), 'issue': L[i][0], 'label': L[i][1], 'passed': m['result'] == 'a', 'yes': float(y.group(1)),
                'yesVotes': int(yv.group(1).replace(',', '')) if yv else None, 'noVotes': int(nv.group(1).replace(',', '')) if nv else None})
json.dump(out, open(sys.argv[2], 'w', encoding='utf8'), ensure_ascii=False, indent=0)
print(len(out), 'measures')
